SELECT id, name, city_id, address, description, ticket_price, opening_hours, latitude, longitude, images, rating, view_count, created_at, updated_at FROM attraction WHERE city_id = #{cityId}
AND (rating < #{lastRating} OR (rating = #{lastRating} AND id < #{lastId}))
ORDER BY rating DESC, id DESC LIMIT #{size}

SELECT id, name, city_id, address, description, ticket_price, opening_hours, latitude, longitude, images, rating, view_count, created_at, updated_at FROM attraction
AND (rating < #{lastRating} OR (rating = #{lastRating} AND id < #{lastId}))
ORDER BY rating DESC, id DESC LIMIT #{size}

SELECT id, latitude, longitude
FROM attraction
WHERE id = #{attractionId}
